package com.priperi;
import org.junit.Test;import static org.junit.Assert.*;import java.io.*;import java.nio.file.*;import java.security.*;import java.util.*;
public class TransferFormatsTest {
 private TransferPhrase words()throws Exception{return new TransferPhrase(Files.newInputStream(Paths.get("src/main/res/raw/bip39_english.txt")));}
 @Test public void bip39Standard256BitVectorsAndQrRoundTrip()throws Exception{byte[] zero=new byte[32],ones=new byte[32];Arrays.fill(ones,(byte)255);TransferPhrase p=words();assertEquals(String.join(" ",Collections.nCopies(23,"abandon"))+" art",p.encode(zero));assertEquals(String.join(" ",Collections.nCopies(23,"zoo"))+" vote",p.encode(ones));assertArrayEquals(zero,p.decode(p.qr(zero)));byte[] random=TransferPhrase.fresh();assertArrayEquals(random,p.decode(p.encode(random).toUpperCase(Locale.ROOT)));}
 @Test public void wrongWordCountUnknownWordsChecksumAndForeignQrAreRejected()throws Exception{TransferPhrase p=words();for(String value:new String[]{"abandon",String.join(" ",Collections.nCopies(24,"abandon")),String.join(" ",Collections.nCopies(24,"unknownword")),"https://example.invalid/"+p.encode(new byte[32]),"x".repeat(513)})try{p.decode(value);fail(value);}catch(GeneralSecurityException expected){}}
 @Test public void bothTransferWordsAndCurrentPasswordAreRequiredAndCapsuleIsAuthenticated()throws Exception{byte[] secret=TransferPhrase.fresh(),plain="Synthetic private transfer data".getBytes();char[] pass="Current-Password-2026!".toCharArray();String capsule=TransferCipher.seal(plain,secret,pass);assertArrayEquals(plain,TransferCipher.open(capsule,secret,pass));try{TransferCipher.open(capsule,secret,"Wrong-Password-2026!".toCharArray());fail();}catch(GeneralSecurityException expected){}try{TransferCipher.open(capsule,TransferPhrase.fresh(),pass);fail();}catch(GeneralSecurityException expected){}byte[] tampered=Base64.getDecoder().decode(capsule);tampered[tampered.length-1]^=1;try{TransferCipher.open(Base64.getEncoder().encodeToString(tampered),secret,pass);fail();}catch(GeneralSecurityException expected){}assertNotEquals(capsule,TransferCipher.seal(plain,secret,pass));}
 @Test public void capsuleSizeHeaderAndEncodingAreBounded()throws Exception{for(String value:new String[]{"not base64",Base64.getEncoder().encodeToString(new byte[100]),"A".repeat(32769)})try{TransferCipher.open(value,new byte[32],"Current-Password-2026!".toCharArray());fail();}catch(GeneralSecurityException expected){}try{TransferCipher.seal(new byte[TransferCipher.MAX_PLAIN+1],new byte[32],"Current-Password-2026!".toCharArray());fail();}catch(GeneralSecurityException expected){}}
 @Test public void delegationPreservesRootTrustAndAllowsNewKeystoreEquivalentSigner()throws Exception{KeyPair root=KeyDelegation.temporaryKey(),temporary=KeyDelegation.temporaryKey(),device=KeyDelegation.temporaryKey();String uid=UUID.randomUUID().toString(),fp="a".repeat(64),r=KeyDelegation.publicValue(root),t=KeyDelegation.publicValue(temporary),d=KeyDelegation.publicValue(device);List<KeyDelegation.Certificate> chain=List.of(new KeyDelegation.Certificate(t,KeyDelegation.sign(root.getPrivate(),KeyDelegation.context(uid,fp,r,t).getBytes())),new KeyDelegation.Certificate(d,KeyDelegation.sign(temporary.getPrivate(),KeyDelegation.context(uid,fp,t,d).getBytes())));byte[] content="Synthetic envelope or archive".getBytes();String signature=KeyDelegation.sign(device.getPrivate(),content);KeyDelegation.verifyAuthorized(uid,fp,r,chain,content,signature);try{KeyDelegation.verifyAuthorized(uid,fp,r,chain,content,KeyDelegation.sign(temporary.getPrivate(),content));fail("Temporary handoff key authorised a message");}catch(GeneralSecurityException expected){}KeyDelegation.verifyAuthorized(uid,fp,r,chain,content,KeyDelegation.sign(root.getPrivate(),content));try{KeyDelegation.verifyAuthorized(UUID.randomUUID().toString(),fp,r,chain,content,signature);fail();}catch(GeneralSecurityException expected){}try{KeyDelegation.verifyAuthorized(uid,fp,r,List.of(),content,signature);fail();}catch(GeneralSecurityException expected){}}
 @Test public void delegationRejectsWrongParentLoopsAndUnboundedChains()throws Exception{KeyPair root=KeyDelegation.temporaryKey(),other=KeyDelegation.temporaryKey();String uid=UUID.randomUUID().toString(),fp="a".repeat(64),r=KeyDelegation.publicValue(root),o=KeyDelegation.publicValue(other);for(List<KeyDelegation.Certificate> chain:List.of(List.of(new KeyDelegation.Certificate(o,KeyDelegation.sign(other.getPrivate(),KeyDelegation.context(uid,fp,r,o).getBytes()))),List.of(new KeyDelegation.Certificate(r,KeyDelegation.sign(root.getPrivate(),KeyDelegation.context(uid,fp,r,r).getBytes()))),Collections.nCopies(33,new KeyDelegation.Certificate(o,"A".repeat(88)))))try{KeyDelegation.keys(uid,fp,r,chain);fail();}catch(GeneralSecurityException expected){}}
 @Test public void transferArchiveAuthenticatesWholeSnapshotAndRejectsWrongKeyOrIdentity()throws Exception{byte[] key=new byte[32];new SecureRandom().nextBytes(key);KeyPair signer=KeyDelegation.temporaryKey();String uid=UUID.randomUUID().toString(),fp="a".repeat(64),publicKey=KeyDelegation.publicValue(signer);ByteArrayOutputStream output=new ByteArrayOutputStream();byte[] record=new byte[100000];new SecureRandom().nextBytes(record);TransferArchive.write(output,key,TransferArchive.salt(),uid,fp,accept->accept.accept(record),value->Base64.getDecoder().decode(KeyDelegation.sign(signer.getPrivate(),value)),()->{});byte[] archive=output.toByteArray();int n=TransferArchive.read(new ByteArrayInputStream(archive),key,uid,fp,bytes->assertArrayEquals(record,bytes),(value,signature)->{if(!KeyDelegation.verify(publicKey,value,Base64.getEncoder().encodeToString(signature)))throw new GeneralSecurityException();},()->{});assertEquals(1,n);try{TransferArchive.read(new ByteArrayInputStream(archive),new byte[32],uid,fp,null,(v,s)->{},()->{});fail();}catch(IOException|GeneralSecurityException expected){}archive[archive.length-1]^=1;try{TransferArchive.read(new ByteArrayInputStream(archive),key,uid,fp,null,(v,s)->{},()->{});fail();}catch(IOException|GeneralSecurityException expected){}}
}
